mapper.select:
select * from `order`
where id = #{id}
  and buyer_id = #{buyerId}

mapper.update:
update `order`
set status = #{newStatus},
    close_time = #{closeTime},
    update_time = now(),
    update_user = #{buyerId},
    version = version + 1
where id = #{id}
  and buyer_id = #{buyerId}
  and status = #{oldStatus}

update `order`
set status = #{newStatus},
    complete_time = #{completeTime},
    update_time = now(),
    update_user = #{buyerId},
    version = version + 1
where id = #{id}
  and buyer_id = #{buyerId}
  and status = #{oldStatus}

mapper.select:
select o.id, o.order_no, o.goods_id, o.seller_id, o.buyer_id, o.amount, o.status, o.expire_time, o.pay_time, o.close_time, o.complete_time, o.create_time, os.goods_title, os.goods_cover, os.goods_price, os.seller_name, os.seller_phone, os.buyer_name, os.buyer_phone, os.meet_location, os.meet_time, os.remark from `order` o left join order_snapshot os on o.id = os.order_id where o.buyer_id = #{buyerId}
and o.status = #{dto.status}
order by o.create_time desc

select o.id, o.order_no, o.goods_id, o.seller_id, o.buyer_id, o.amount, o.status, o.expire_time, o.pay_time, o.close_time, o.complete_time, o.create_time, os.goods_title, os.goods_cover, os.goods_price, os.seller_name, os.seller_phone, os.buyer_name, os.buyer_phone, os.meet_location, os.meet_time, os.remark from `order` o left join order_snapshot os on o.id = os.order_id where o.seller_id = #{sellerId}
and o.status = #{dto.status}
order by o.create_time desc
